import type { Env,AuthenticatedSurfaceDiagnosticMessage } from "./types";
import { executeAuthenticatedSurfaceDiagnostic,type AuthenticatedSurfaceDiagnosticInput } from "./authenticated-surface-diagnostic";
type Row={request_id:string;profile_id:string;expected_profile_version:number;tenant_id:string;owner_id:string;state:string;attempt_count:number;expires_at:string};
export type DiagnosticTriggerResult={status:"ignored"|"completed"|"failed"|"expired";requestId:string;failureCode?:string};
const SAFE=new Set(["surfaceKind","hostname","pathnameCategory","pathnamePattern","authOriginValid","authFlowLineageValid","formCountCategory","activeFormPresent","activeFormUnambiguous","identifierTextboxPresent","identifierTextboxVisible","identifierTextboxEnabled","identifierTextboxFocusable","identifierTextboxInsideActiveForm","knownIdentifierTextboxLabel","passwordTextboxPresent","passwordTextboxVisible","passwordTextboxEnabled","passwordTextboxFocusable","passwordTextboxInsideActiveForm","passwordAutocompleteCategory","knownPasswordTextboxLabel","identifierTextboxCountCategory","passwordTextboxCountCategory","knownControlLabels","submitControlSemanticKind","submitControlVisible","submitControlEnabled","captchaWidgetPresent","securityVerificationSurfacePresent","documentCountCategory","iframeCountCategory","domNodeCountCategory","accessibilityNodeCountCategory","bridgeProtocolVersion","trustedObservationSchemaVersion","browserProvider","browserBackend","browserGeneration"]);
export async function dispatchPendingAuthenticatedSurfaceDiagnostics(env:Pick<Env,"DB"|"WEB_OPERATOR_QUEUE">,now=new Date()){const time=now.toISOString();await env.DB.prepare(`UPDATE authenticated_surface_diagnostic_requests SET state='expired',completed_at=?,failure_code='REQUEST_EXPIRED' WHERE state IN ('pending','queued') AND expires_at<=?`).bind(time,time).run();const rows=await env.DB.prepare(`SELECT request_id FROM authenticated_surface_diagnostic_requests WHERE state='pending' AND expires_at>? AND attempt_count=0 ORDER BY created_at,request_id LIMIT 10`).bind(time).all<{request_id:string}>();let count=0;for(const row of rows.results){await env.WEB_OPERATOR_QUEUE.send({type:"authenticated_surface_diagnostic",requestId:row.request_id} satisfies AuthenticatedSurfaceDiagnosticMessage);const update=await env.DB.prepare(`UPDATE authenticated_surface_diagnostic_requests SET state='queued',queued_at=? WHERE request_id=? AND state='pending'`).bind(time,row.request_id).run();if(Number(update.meta.changes)===1)count++;}return count;}
export async function processAuthenticatedSurfaceDiagnostic(env:Env,message:AuthenticatedSurfaceDiagnosticMessage,now=new Date(),execute:(input:AuthenticatedSurfaceDiagnosticInput,env:Env,id:string)=>Promise<Response>=executeAuthenticatedSurfaceDiagnostic):Promise<DiagnosticTriggerResult>{const time=now.toISOString();const claim=await env.DB.prepare(`UPDATE authenticated_surface_diagnostic_requests SET state='running',started_at=?,attempt_count=1,browser_generation=1 WHERE request_id=? AND state IN ('pending','queued') AND expires_at>? AND attempt_count=0`).bind(time,message.requestId,time).run();if(Number(claim.meta.changes)!==1){const row=await load(env.DB,message.requestId);return{status:row?.state==="expired"?"expired":"ignored",requestId:message.requestId};}const row=await load(env.DB,message.requestId);if(!row)return{status:"ignored",requestId:message.requestId};const auth=await env.DB.prepare(`SELECT p.version,p.tenant_id,p.owner_id,p.revoked_at,a.disabled_at FROM authenticated_site_profiles p JOIN accounts a ON a.id=p.owner_id WHERE p.id=?`).bind(row.profile_id).first<Record<string,unknown>>();const failure=!auth?"PROFILE_OR_OWNER_MISSING":row.tenant_id!==row.owner_id?"TENANT_OWNER_MISMATCH":Number(auth.version)!==row.expected_profile_version?"PROFILE_VERSION_MISMATCH":auth.revoked_at?"PROFILE_REVOKED":auth.disabled_at?"OWNER_DISABLED":undefined;if(failure)return finish(env.DB,row.request_id,"failed",failure);let response:Response;try{response=await execute({authenticatedProfileId:row.profile_id,tenantId:row.tenant_id,ownerId:row.owner_id,expectedProfileVersion:row.expected_profile_version},env,row.request_id)}catch{return finish(env.DB,row.request_id,"failed","INTERNAL_EXECUTION_FAILURE");}const body:Record<string,unknown>=await response.json<Record<string,unknown>>().catch(()=>({}));const diagnostic=safe(body.diagnostic);return finish(env.DB,row.request_id,response.ok?"completed":"failed",response.ok?undefined:stringValue(body.error)??"DIAGNOSTIC_FAILED",diagnostic);}
export async function cancelAuthenticatedSurfaceDiagnostic(db:D1Database,id:string,now=new Date()){const result=await db.prepare(`UPDATE authenticated_surface_diagnostic_requests SET state='cancelled',completed_at=? WHERE request_id=? AND state IN ('pending','queued')`).bind(now.toISOString(),id).run();return Number(result.meta.changes)===1;}
async function load(db:D1Database,id:string){return db.prepare(`SELECT request_id,profile_id,expected_profile_version,tenant_id,owner_id,state,attempt_count,expires_at FROM authenticated_surface_diagnostic_requests WHERE request_id=?`).bind(id).first<Row>();}async function finish(db:D1Database,id:string,state:"completed"|"failed",failureCode?:string,safeDiagnostic:Record<string,string|number|boolean>={}){await db.prepare(`UPDATE authenticated_surface_diagnostic_requests SET state=?,failure_code=?,safe_diagnostic_json=?,completed_at=? WHERE request_id=? AND state='running' AND attempt_count=1`).bind(state,failureCode??null,JSON.stringify(safeDiagnostic),new Date().toISOString(),id).run();return{status:state,requestId:id,failureCode} as DiagnosticTriggerResult;}function safe(value:unknown){const source=value&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,unknown>:{};const out:Record<string,string|number|boolean>={};for(const [key,item] of Object.entries(source))if(SAFE.has(key)&&(typeof item==="string"||typeof item==="number"||typeof item==="boolean"))out[key]=item;return out;}function stringValue(value:unknown){return typeof value==="string"?value:undefined;}
