 for(const m of text.matchAll(pattern))out.push({text:m[0],key:`${months.indexOf((m[2]??m[3]).toLowerCase().replace(/^oct\.?$/,'october'))+1}-${Number(m[1]??m[4])}${m[5]?`-${m[5]}`:''}`,index:m.index!});
